// Differential test harness: compares the Python executable against the Node port.
//
// Usage:
//   node /workspace/harness/compare.mjs <corpus.json> [--impl /output/test2.mjs] [--quiet] [--max N]
//
// Corpus format: JSON array whose entries are either
//   - a string           -> argv becomes ["--a", <string>]
//   - an array of strings -> used verbatim as argv
//
// Compares stdout, stderr and exit code byte-for-byte and prints every mismatch
// with fully escaped payloads so nothing is lost to shell quoting.

import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';

const EXE = '/workspace/dataset/test2_executable';

const rawArgs = process.argv.slice(2);
let corpusPath = null;
let impl = '/output/test2.mjs';
let quiet = false;
let max = Infinity;
for (let i = 0; i < rawArgs.length; i++) {
  const a = rawArgs[i];
  if (a === '--impl') impl = rawArgs[++i];
  else if (a === '--quiet') quiet = true;
  else if (a === '--max') max = Number(rawArgs[++i]);
  else corpusPath = a;
}
if (!corpusPath) {
  console.error('usage: node compare.mjs <corpus.json> [--impl path] [--quiet] [--max N]');
  process.exit(64);
}

const entries = JSON.parse(readFileSync(corpusPath, 'utf8'));
if (!Array.isArray(entries)) {
  console.error('corpus must be a JSON array');
  process.exit(64);
}

const run = (cmd, args) => {
  const r = spawnSync(cmd, args, { encoding: 'utf8', maxBuffer: 1 << 28 });
  if (r.error) return { out: '', err: String(r.error), code: -999 };
  return { out: r.stdout ?? '', err: r.stderr ?? '', code: r.status === null ? -1 : r.status };
};

// argparse prints the program name in usage/error text; normalise it so only
// real behavioural differences are reported.
const normalise = (s) => s.split('test2_executable').join('PROG').split('test2.mjs').join('PROG');

let pass = 0;
const fails = [];
let n = 0;
for (const entry of entries) {
  if (n >= max) break;
  n++;
  const argv = Array.isArray(entry) ? entry.map(String) : ['--a', String(entry)];
  const expected = run(EXE, argv);
  const actual = run('node', [impl, ...argv]);
  const same =
    expected.out === actual.out &&
    normalise(expected.err) === normalise(actual.err) &&
    expected.code === actual.code;
  if (same) pass++;
  else fails.push({ argv, expected, actual });
}

if (!quiet) {
  for (const f of fails) {
    console.log('================ MISMATCH ================');
    console.log('argv     : ' + JSON.stringify(f.argv));
    console.log('exp.out  : ' + JSON.stringify(f.expected.out));
    console.log('act.out  : ' + JSON.stringify(f.actual.out));
    if (normalise(f.expected.err) !== normalise(f.actual.err)) {
      console.log('exp.err  : ' + JSON.stringify(f.expected.err));
      console.log('act.err  : ' + JSON.stringify(f.actual.err));
    }
    if (f.expected.code !== f.actual.code) {
      console.log('exp.code : ' + f.expected.code + '   act.code : ' + f.actual.code);
    }
  }
}
console.log(`\nRESULT: ${pass}/${n} passed, ${fails.length} failed  (corpus=${corpusPath})`);
process.exit(fails.length === 0 ? 0 : 1);

