// Scratch generator for my own spot-checks (kept out of /workspace/corpus so the
// workflow agents own that directory).
import { writeFileSync } from 'node:fs';

const cases = [
  'BEGIN /*c*/ x; SELECT 1;',
  'BEGIN',
  'CREATE TABLE t(a); DECLARE x; SELECT 1;',
  'SELECT 1; CREATE PROC p AS DECLARE x; SELECT 2;',
  "SELECT '中文;'; SELECT 2",
  "SELECT 'a b'; SELECT 2",
  "SELECT '\u{1F600}'; SELECT 2",
  "SELECT '​x'; SELECT 2",
  "SELECT 'tab\there'",
  "SELECT 'q'' and \"d\"'",
  "SELECT '　x'",
  "SELECT 'x'",
  "SELECT ' x'",
  "SELECT 'x'",
  "SELECT 'x'",
  "SELECT 'back\\\\slash'",
];
writeFileSync('/tmp/spot/uni.json', JSON.stringify(cases, null, 0));
console.log('wrote', cases.length);

